UPDATE storage_file
SET status = #{targetStatus}, content_type = #{contentType}, size_bytes = #{sizeBytes},
object_key = #{objectKey}, ready_expires_at = #{readyExpiresAt}
WHERE id = #{id} AND status = #{expectedStatus}

UPDATE storage_file
status = #{targetStatus.value}, ready_expires_at = #{readyExpiresAt.value}, ready_expires_at = NULL, next_delete_at = #{nextDeleteAt.value}, next_delete_at = NULL,
WHERE id = #{id} AND status = #{expectedStatus}

mapper.select:
SELECT

FROM storage_file
WHERE upload_object_cleaned = 0 AND upload_expires_at <= #{now}
ORDER BY upload_expires_at LIMIT #{limit}

WITH candidate AS MATERIALIZED (
    SELECT id FROM storage_file
    WHERE status IN
    #{status}
    AND COALESCE(next_delete_at, #{now}) <= #{now}
    AND (delete_lease_until IS NULL OR delete_lease_until <= #{now})
    ORDER BY id LIMIT #{limit}
), leased AS (
    UPDATE storage_file AS file
    SET status = #{targetStatus}, delete_lease_owner = #{leaseOwner}, delete_lease_until = #{leaseUntil}
    FROM candidate
    WHERE file.id = candidate.id
      AND file.status IN
      #{status}
      AND COALESCE(file.next_delete_at, #{now}) <= #{now}
      AND (file.delete_lease_until IS NULL OR file.delete_lease_until <= #{now})
    RETURNING file.id, file.uploader_principal_id, file.scene,
              file.target_resource_type, file.target_resource_id,
              file.backend_id, file.container_name, file.upload_object_key,
              file.object_key, file.filename, file.declared_content_type,
              file.declared_size_bytes, file.content_type, file.size_bytes,
              file.status, file.upload_expires_at, file.ready_expires_at,
              file.upload_object_cleaned
)
SELECT  FROM leased ORDER BY id

