UPDATE storage_file
status = #{targetStatus.value}, next_delete_at = #{retryAt.value}, next_delete_at = NULL, delete_lease_owner = NULL, delete_lease_until = NULL, delete_attempts = delete_attempts + CASE WHEN #{incrementAttempts} THEN 1 ELSE 0 END
WHERE id = #{id} AND status = #{expectedStatus} AND delete_lease_owner = #{leaseOwner}
